use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{ManifestFormat, NpmAccess, RegistryKey, Version, VersionGrammar};

/// Ecosystem supported by callisto.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
#[non_exhaustive]
pub enum Ecosystem {
    Cargo,
    Npm,
    // Demand-gated ecosystems:
    Pypi,
    Go,
    Maven,
    NuGet,
    Deno,
    Jsr,
}

impl Ecosystem {
    /// Precedence when one directory declares several canonical manifests: Cargo, then npm, then PyPI, then the rest.
    /// Named rather than derived from the variant order so it survives new variants.
    pub fn primary_priority(self) -> u8 {
        match self {
            Ecosystem::Cargo => 0,
            Ecosystem::Npm => 1,
            Ecosystem::Pypi => 2,
            _ => u8::MAX,
        }
    }

    /// The three ecosystems package *identity discovery* treats as
    /// canonical -- each has exactly one manifest format
    /// ([`Ecosystem::canonical_manifest_format`]) that carries a package's
    /// name and (usually) version. Deliberately excludes the other,
    /// demand-gated ecosystems in this enum (Go, Maven, NuGet, ...), which
    /// either have no canonical-identity manifest wired up yet or aren't
    /// part of this duplication (see audit pattern B).
    pub const CANONICAL: [Ecosystem; 3] = [Ecosystem::Cargo, Ecosystem::Npm, Ecosystem::Pypi];

    /// The manifest format that carries this ecosystem's package identity
    /// (name and version), for the [`Self::CANONICAL`] ecosystems only.
    /// `None` for every other ecosystem in this enum.
    pub fn canonical_manifest_format(&self) -> Option<ManifestFormat> {
        match self {
            Ecosystem::Cargo => Some(ManifestFormat::CargoToml),
            Ecosystem::Npm => Some(ManifestFormat::PackageJson),
            Ecosystem::Pypi => Some(ManifestFormat::PyprojectToml),
            _ => None,
        }
    }

    pub fn prefix(&self) -> &'static str {
        match self {
            Ecosystem::Cargo => "cargo",
            Ecosystem::Npm => "npm",
            Ecosystem::Pypi => "pypi",
            Ecosystem::Go => "go",
            Ecosystem::Maven => "maven",
            Ecosystem::NuGet => "nuget",
            Ecosystem::Deno => "deno",
            Ecosystem::Jsr => "jsr",
        }
    }
    {
      "name": "[[package]] match",
      "signature": "match = \"<ecosystem>/<name>\"",
      "description": "Exact package id, ecosystem-qualified. Ecosystem prefixes: cargo, npm, pypi.",
      "error_conditions": [
        "A name without its ecosystem is E317; an empty, absolute, `..`-containing or otherwise unparseable id fails config loading."
      ]
    },
    {
      "name": "[[package-set]] match",
      "signature": "match = \"<ecosystem>/<glob>\"",
      "description": "Glob over package names, scoped to one ecosystem.",
      "error_conditions": [
        "A glob without its ecosystem is E317; an invalid glob fails config loading."
      ]
    }
  ],
  "acceptance_criteria": [
## Resolving ambiguity

A workspace can hold `cargo/foo` and `npm/foo` as separate packages; ambiguity is resolved where a lookup happens. Qualified selectors work before and after promotion, and the colon form is rejected with E316. Config and CLI selectors must be canonical (`ecosystem/name`); a bare name is E317 (see [ADR 12](../adr/0012-canonical-distribution-release-ownership.md)).

- `aggregate::resolve_target_package` resolves changeset entries through `IdentityIndex::resolve_id`, which maps qualified native distribution names to their owner and rejects ambiguous bare names. `status` attributes changeset entries and checks their well-formedness through the same resolver.- `[[package]]` rules use `config::resolve::resolve_package_config`: the first rule in declaration order whose ecosystem the package has and whose name matches. It never sorts the rules. Config rejects a rule without its ecosystem (E317), so every rule is ecosystem-qualified.
- `[[package-set]]` is a fallback applied in `ManifestWalkResolver::build` (`crates/callisto-graph/src/walk.rs`) only when no `[[package]]` rule matched. Patterns (`config/pattern.rs`) are globs over the name with a required ecosystem prefix (a bare pattern is E317), tested against every ecosystem the package has a manifest in.

## Loading a workspace

    #[diagnostic(code(E316), help("Write the ecosystem and name with a slash: `{canonical}`."))]
    ColonReference {
        context: String,
        given: String,
        canonical: String,
    },

    #[error("{context}: `{given}` does not name its ecosystem")]
    #[diagnostic(
        code(E317),
        help("Write the ecosystem and name with a slash, such as `cargo/{given}`, `npm/{given}` or `pypi/{given}`.")
    )]
    BareReference { context: String, given: String },

