/// Ecosystem workspace protocol type.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum WorkspaceKind {
    Pnpm,
    Yarn,
    Npm,
}

/// Retains the protocol spelling; aliases name a distribution and relative paths name a directory.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct WorkspaceSpec {
    pub kind: WorkspaceKind,
    pub suffix: String,
}

impl WorkspaceSpec {
    pub fn alias(&self) -> Option<&str> {
        if self.relative_path().is_some() {
            return None;
        }
        self.suffix
            .rsplit_once('@')
            .and_then(|(name, _)| (!name.is_empty() && !name.contains([':', ' ', '\\'])).then_some(name))
    }

    /// Bind this directory relative to the declaring manifest to an admitted npm member.
    pub fn relative_path(&self) -> Option<&str> {
        (self.suffix.starts_with("../") || self.suffix.starts_with("./")).then_some(self.suffix.as_str())
    }

    pub fn range(&self) -> Option<&str> {
        if self.relative_path().is_some() {
            return None;
        }
        let range = if self.alias().is_some() {
            self.suffix.rsplit_once('@').map(|(_, range)| range)?
        } else {
            self.suffix.as_str()
        };
        (!matches!(range, "" | "*" | "^" | "~")).then_some(range)
    }

    /// Coverage assumes the workspace target has already been resolved locally.
    pub fn coverage(&self, version: &Version) -> Result<Coverage, GrammarMismatch> {
        let Some(range) = self.range() else {
            return Ok(Coverage::Covers);
        };
        let Some(requirements) = range
            .split("||")
            .map(|arm| Self::parse_range_arm(arm.trim()))
            .collect::<Option<Vec<_>>>()
        else {
            return Ok(Coverage::Unknown);
        };
        for requirement in requirements {
            if requirement.matches(version)? {
                return Ok(Coverage::Covers);
            }
        }
        Ok(Coverage::DoesNotCover)
    }

    fn parse_range_arm(range: &str) -> Option<VersionReq> {
        if range.is_empty() {
            return None;
        }
        VersionReq::parse(range, Ecosystem::Npm).ok()
    }

    pub fn with_range(&self, range: &str) -> Self {
        let suffix = match self.alias() {
            Some(target) => format!("{target}@{range}"),
            None => range.to_string(),
        };
        Self {
            kind: self.kind,
            suffix,
        }
    }
}

/// Evaluation of whether a version specification covers a candidate version.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum Coverage {
    Covers,
    DoesNotCover,
    Unknown,
        npm_role_from_doc(&self.doc)
    }

    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
        Ok(match self.doc.get("bin") {
            // npm installs a string `bin` under the unscoped package name.
            Some(Value::String(_)) => npm_package_name(&self.doc)
                .map(|name| name.rsplit('/').next().unwrap_or(name).to_string())
                .into_iter()
                .collect(),
            Some(Value::Object(bins)) => bins.keys().cloned().collect(),
            _ => Vec::new(),
        })
    }
}

fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
    if let Some(rest) = s.strip_prefix("workspace:") {
        if let Some(kind) = ws_kind {
            return DepSpec::WorkspaceProtocol(WorkspaceSpec {
                kind,
                suffix: rest.to_string(),
            });
        }
        return DepSpec::Opaque(format!("workspace:{rest}"));
    }
    if let Some(rest) = s.strip_prefix("catalog:") {
        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
        return DepSpec::Catalog(name);
    }

    if crate::common::is_bare_semver(s)
        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
    {
        return DepSpec::Exact(v);
    }

    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
        return DepSpec::Range(req, s.to_string());
    }

    DepSpec::Opaque(s.to_string())
}

